/* ═══ Usuários Stats — perfis + atividade proxy via kanban ═══ */
const USR_ROLE_LABEL={superadmin:"Super Admin",admin:"Admin",user:"Usuário",ia:"🤖 IA",placeholder:"placeholder",["sem-perfil"]:"sem perfil"};
const USR_ROLE_COLOR={superadmin:"#D4A853",admin:"#60A5FA",user:"#A1A1AA",ia:"#A78BFA",placeholder:"#6B7280",["sem-perfil"]:"#6B7280"};
function _normName(s){return(s||"").trim().toLowerCase()}
function _fmtAgo(ts){if(!ts)return"—";const d=Math.floor((Date.now()-ts)/86400000);if(d<=0)return"hoje";if(d===1)return"ontem";if(d<30)return`há ${d}d`;if(d<365)return`há ${Math.floor(d/30)}m`;return`há ${Math.floor(d/365)}a`}
