  const orphanCount=enriched.filter(u=>u._orphan&&u.role!=="placeholder").length;
  const totalCards7=enriched.reduce((s,u)=>s+u._d7,0);
  const T_DIM="rgba(255,255,255,0.4)",T_MED="rgba(255,255,255,0.7)",BRD="rgba(255,255,255,0.08)",CBG="rgba(255,255,255,0.02)",ACC="#D4A853",GRN="#10B981";
