/* ═══ Jornada do Projeto — visão consolidada CEO (Operacional + Projetos) ═══ */
const JOR_OP_ESTEIRA=[["entrada","Obras Novas"],["projeto","Projeto"],["pendente","Pendente"],["primeira-vistoria","1ª Vistoria"],["pre-cronograma","Pré-Crono"],["segunda-vistoria","2ª Vistoria"],["entrega-material","Entrega Material"],["obras-liberadas","Obras Liberadas"],["cronograma-final","Crono Final"],["acompanhamento","Acompanhamento"],["obras-finalizadas","Finalizadas"]];
